result = Broker.CALCULATE(
    num_matching_customers = COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), "j") | ENDSWITH(LOWER(name), "ez")) &
            ENDSWITH(LOWER(state), "a")
        )
    )
)

distinct_ticker_ids_on_or_after_date = Tickers.WHERE(
    HAS(historical_prices.WHERE(date >= "2023-04-01")) == 1
).CALCULATE(
    ticker_id=_id
)

transactions_from_recent_customers = Broker.CALCULATE(
    num_transactions_recent_joiners=COUNT(
        Customers.WHERE(
            DATEDIFF("days", join_date, 'now') <= 70
        ).transactions_made
    )
)
